// Solder Hasp Vault Enclosure - Procedural OpenSCAD
$fn = 36;
wall = 2.5;
inner_x = 119.0;
inner_y = 93.0;
inner_z = 39.0;
outer_x = inner_x + 2*wall;
outer_y = inner_y + 2*wall;
outer_z = inner_z + 2*wall;

module hasp_base() {
  difference() {
    cube([outer_x, outer_y, outer_z]);
    translate([wall, wall, wall])
      cube([inner_x, inner_y, inner_z + 1]);
    // Servo latch tongue slot
    translate([outer_x - wall - 1, inner_y/2, wall + 10])
      cube([wall + 2, 14, 8]);
    // Rear DC power pass-through
    translate([-1, 20, wall + 4])
      cube([wall + 2, 10, 10]);
  }
  // Servo mounting bracket
  translate([wall + 75, wall + 8, wall]) {
    cube([24, 13, 16]);
  }
}

module hasp_lid() {
  difference() {
    cube([outer_x, outer_y, wall + 3]);
    // Bevel frame for OLED
    translate([wall + 42, wall + 40, -1])
      cube([26, 16, wall + 5]);
    // Thumb trigger opening
    translate([wall + 42, wall + 18, -1])
      cylinder(r = 6, h = wall + 5);
  }
}

hasp_base();
translate([0, outer_y + 15, 0]) hasp_lid();

