#include <Servo.h>
#include <Wire.h>

Servo lockServo;
const int SERVO_PIN = 9;
const int BUZZER_PIN = 8;
const int TRIGGER_PIN = 2;

const int POS_LOCKED = 0;
const int POS_UNLOCKED = 90;

void setup() {
  Serial.begin(9600);
  pinMode(TRIGGER_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  lockServo.attach(SERVO_PIN);
  lockServo.write(POS_LOCKED);

  Serial.println(F("--- Solder Hasp Smart Lockbox Ready ---"));
  Serial.println(F("State: LOCKED | Monitoring Auth Sensor"));
}

void loop() {
  // Inverted because of INPUT_PULLUP (LOW = pressed/triggered)
  int authState = digitalRead(TRIGGER_PIN);

  if (authState == LOW) {
    Serial.println(F("ACCESS_GRANTED: UNLOCKED"));
    digitalWrite(BUZZER_PIN, HIGH);
    delay(100);
    digitalWrite(BUZZER_PIN, LOW);

    lockServo.write(POS_UNLOCKED);
    delay(3000); // Hold open for 3 seconds

    Serial.println(F("AUTO_TIMEOUT: RELOCKING"));
    lockServo.write(POS_LOCKED);
  } else {
    Serial.println(F("STATUS: LOCKED"));
  }

  delay(500);
}
